add_filter( 'excerpt_more', 'perfectpixel_read_more_excerpt', 20 );
add_filter( 'the_content_more_link', 'perfectpixel_read_more_content_link', 20 );

function perfectpixel_read_more_excerpt( $more ) {
	if ( is_admin() || is_feed() ) {
		return $more;
	}
	return '&hellip; <a class="more-link" href="' . esc_url( get_permalink() ) . '">' . esc_html( '{{read_more_text}}' ) . '</a>';
}

function perfectpixel_read_more_content_link() {
	return '<a class="more-link" href="' . esc_url( get_permalink() . '#more-' . get_the_ID() ) . '">' . esc_html( '{{read_more_text}}' ) . '</a>';
}
